extern "C" void abort ();

struct T
{
  int x, y;

  auto sum_func (int n)
  {
    auto fn = [=](int m) -> int
      {
	int v;
	v = (x + y) * n + m;
	return v;
      };
    return fn;
  }

  auto sum_func_offload (int n)
  {
